import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.WFmvnizL.js";const p=JSON.parse('{"title":"Nezha Monitoring V2 version and compatibility guide","description":"Understand Nezha Monitoring V2 product generation, independent Dashboard and Agent releases, the /api/v1 route namespace, legacy V0/V1 documentation, and safe upgrade checks.","frontmatter":{"title":"Nezha Monitoring V2 version and compatibility guide","description":"Understand Nezha Monitoring V2 product generation, independent Dashboard and Agent releases, the /api/v1 route namespace, legacy V0/V1 documentation, and safe upgrade checks.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/version-compatibility.md","filePath":"en_US/guide/version-compatibility.md","lastUpdated":1792674226000}'),r={name:"en_US/guide/version-compatibility.md"};function i(s,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="nezha-monitoring-v2-version-and-compatibility-guide" tabindex="-1">Nezha Monitoring V2 version and compatibility guide <a class="header-anchor" href="#nezha-monitoring-v2-version-and-compatibility-guide" aria-label="Permalink to &quot;Nezha Monitoring V2 version and compatibility guide&quot;">​</a></h1><p>The current documentation targets <strong>Nezha Monitoring V2</strong>. Separating product generation, component releases, and API versions prevents <code>/api/v1</code>, an old tutorial, or one component tag from being mistaken for a statement that the current product is still V1.</p><h2 id="what-do-the-four-version-labels-mean" tabindex="-1">What do the four version labels mean? <a class="header-anchor" href="#what-do-the-four-version-labels-mean" aria-label="Permalink to &quot;What do the four version labels mean?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td>Product generation</td><td>Nezha Monitoring V2</td><td>Current overall product and documentation generation</td></tr><tr><td>Dashboard release</td><td><code>v2.x.y</code></td><td>Independently published server release from the <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard repository</a></td></tr><tr><td>Agent release</td><td><code>v2.x.y</code></td><td>Independently published client release from the <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent repository</a>; it does not need the same exact number as Dashboard</td></tr><tr><td>API path version</td><td><code>/api/v1/...</code></td><td>REST API route namespace maintained for interface compatibility; it is not the product generation</td></tr></tbody></table><p>Seeing <code>/api/v1/server</code> on a V2 Dashboard is therefore expected. Do not replace routes with <code>/api/v2</code> unless the official code and API documentation explicitly introduce that path.</p><h2 id="must-dashboard-and-agent-have-the-same-version" tabindex="-1">Must Dashboard and Agent have the same version? <a class="header-anchor" href="#must-dashboard-and-agent-have-the-same-version" aria-label="Permalink to &quot;Must Dashboard and Agent have the same version?&quot;">​</a></h2><p>They are released independently, so their patch versions do not have to match. That does not imply every arbitrary cross-version combination is compatible. Recommended practice is to:</p><ol><li>Use stable releases from both repositories in production.</li><li>Read both Dashboard and Agent release notes before upgrading.</li><li>Back up Dashboard data and configuration first.</li><li>Upgrade a small group of nodes and observe connection, state reporting, checks, and remote operations.</li><li>Roll out to the remaining Agents gradually so one change cannot remove visibility from every node at once.</li></ol><p>If Dashboard requests a forced Agent update or logs show protocol, authentication, or field errors, follow the current release notes and issues instead of comparing version strings alone.</p><h2 id="component-responsibilities-and-feature-boundaries" tabindex="-1">Component Responsibilities and Feature Boundaries <a class="header-anchor" href="#component-responsibilities-and-feature-boundaries" aria-label="Permalink to &quot;Component Responsibilities and Feature Boundaries&quot;">​</a></h2><p>Admin and user frontends are released independently. Official Dashboard releases bundle frontends selected by the build-time template manifest; third-party themes may not implement the same features. This guide describes current stable behavior directly.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Current behavior and boundaries</th></tr></thead><tbody><tr><td>Mobile terminal</td><td>The admin frontend provides key controls and a clipboard button; the Agent handles terminal input, sizing, and colors</td></tr><tr><td>GPU memory</td><td>The Agent reports per-card memory, Dashboard relays it, and the default user frontend displays it; memory collection currently supports Linux NVIDIA only</td></tr><tr><td>JWT sessions across IP changes</td><td><code>allow_jwt_ip_change</code> is disabled by default; there is no admin-frontend switch, so use the configuration file or settings API</td></tr><tr><td>Online history</td><td>Dashboard stores online sessions in its database without TSDB; the default user frontend provides an Online tab with a one-day query selected by default</td></tr><tr><td>Online stats range</td><td><code>online_stats_days</code> defaults to 7 days and accepts 7–3650 days, controlling both retention and the maximum query window</td></tr></tbody></table><p>Online history accumulates from received state reports and does not backfill previously unrecorded periods. The default user frontend offers 1/7/30-day options; the API maximum follows configured retention. Independently released components do not need identical version numbers.</p><h2 id="how-should-v0-v1-and-v2-documentation-be-read" tabindex="-1">How should V0, V1, and V2 documentation be read? <a class="header-anchor" href="#how-should-v0-v1-and-v2-documentation-be-read" aria-label="Permalink to &quot;How should V0, V1, and V2 documentation be read?&quot;">​</a></h2><ul><li><strong>V2:</strong> the default target for current installation, configuration, API, and troubleshooting pages.</li><li><strong>V1:</strong> a historical product generation. Follow the current V2 installation and usage documentation rather than copying old configuration or commands.</li><li><strong>V0:</strong> old configuration formats, databases, and login flows may be incompatible with current releases. Pages retained at old URLs are historical references, not instructions for new deployments.</li><li><strong>V1 in a community project name:</strong> when an upstream repository or project name explicitly says V1, the documentation preserves the real name and labels it third-party or historical. It does not invent V2 compatibility.</li></ul><h2 id="common-apparent-version-conflicts" tabindex="-1">Common apparent version conflicts <a class="header-anchor" href="#common-apparent-version-conflicts" aria-label="Permalink to &quot;Common apparent version conflicts&quot;">​</a></h2><h3 id="why-is-the-api-still-api-v1" tabindex="-1">Why is the API still <code>/api/v1</code>? <a class="header-anchor" href="#why-is-the-api-still-api-v1" aria-label="Permalink to &quot;Why is the API still `/api/v1`?&quot;">​</a></h3><p>API version and product generation are independent. The current <a href="/en_US/guide/api.html">API documentation</a> follows routes implemented by Dashboard.</p><h3 id="which-behavior-does-this-documentation-describe" tabindex="-1">Which behavior does this documentation describe? <a class="header-anchor" href="#which-behavior-does-this-documentation-describe" aria-label="Permalink to &quot;Which behavior does this documentation describe?&quot;">​</a></h3><p>Installation, configuration, API, and troubleshooting pages directly describe the current stable behavior. For example, web and Agent communication share a port, and local accounts support OAuth2 binding. Release history is for auditing and provenance, not a prerequisite for current usage steps.</p><h3 id="why-does-a-community-project-page-still-say-v1" tabindex="-1">Why does a community project page still say V1? <a class="header-anchor" href="#why-does-a-community-project-page-still-say-v1" aria-label="Permalink to &quot;Why does a community project page still say V1?&quot;">​</a></h3><p>Community pages describe third-party projects. Their maintainers determine names and compatibility. Official documentation cannot claim V2 support without upstream evidence. Check recent commits, releases, and issues before deployment.</p><h2 id="pre-upgrade-checklist" tabindex="-1">Pre-upgrade checklist <a class="header-anchor" href="#pre-upgrade-checklist" aria-label="Permalink to &quot;Pre-upgrade checklist&quot;">​</a></h2><ul><li>Review <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard Releases</a> and <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent Releases</a>.</li><li>Back up <code>/opt/nezha</code> or the actual mounted data, configuration, and TSDB directories.</li><li>Record current Dashboard and Agent versions, installation method, domains, and reverse proxy configuration.</li><li>Check database migrations, configuration-field changes, and removed features.</li><li>Test login, Agent connectivity, WebSocket, gRPC, notifications, and authorized operations.</li><li>Do not overwrite a current deployment with an old Compose file, configuration example, or binary.</li></ul><p>See <a href="/en_US/guide/dashboard.html">Install Dashboard</a>, <a href="/en_US/guide/agent.html">Install Agent</a>, and <a href="/en_US/guide/q5.html">Backup and recovery</a> for operational steps.</p>',25)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
